"""
PlatformIO pre-build step: gzip web/index.html into include/generated/web_index.h
so the page ships inside the firmware image (no filesystem upload needed).
"""

import gzip
import os

Import("env")  # noqa: F821 (provided by PlatformIO/SCons)

proj = env.subst("$PROJECT_DIR")  # noqa: F821
src = os.path.join(proj, "web", "index.html")
out_dir = os.path.join(proj, "include", "generated")
out = os.path.join(out_dir, "web_index.h")

with open(src, "rb") as f:
    raw = f.read()
gz = gzip.compress(raw, compresslevel=9, mtime=0)

lines = [
    "// Generated by scripts/embed_web.py from web/index.html. Do not edit.",
    "#pragma once",
    "#include <Arduino.h>",
    "",
    f"static const size_t kWebIndexGzLen = {len(gz)};",
    "static const uint8_t kWebIndexGz[] PROGMEM = {",
]
for i in range(0, len(gz), 20):
    lines.append("  " + ",".join(f"0x{b:02X}" for b in gz[i:i + 20]) + ",")
lines += ["};", ""]
text = "\n".join(lines)

os.makedirs(out_dir, exist_ok=True)
old = None
if os.path.exists(out):
    with open(out, "r", encoding="utf-8") as f:
        old = f.read()
if old != text:  # avoid needless rebuilds
    with open(out, "w", encoding="utf-8", newline="\n") as f:
        f.write(text)
print(f"embed_web: index.html {len(raw)} B -> {len(gz)} B gzip")



# Wi-Fi setup portal skin -> include/generated/portal_head.h (a plain string:
# WiFiManager pastes it into the <head> of its own pages).
import re

with open(os.path.join(proj, "web", "portal.html"), "r", encoding="utf-8") as f:
    head = f.read()
head = re.sub(r"<!--.*?-->", "", head, flags=re.S)
head = "\n".join(l.strip() for l in head.splitlines()
                 if l.strip() and not l.strip().startswith("//"))


def squeeze(text):
    """Drop spaces/newlines next to punctuation, outside quotes (heap is tight
    when the portal opens at runtime). Regex literals in portal.html contain
    no quotes or punctuation-adjacent spaces, so they survive."""
    out, quote = [], None
    punct = set("{}();,=+:<>!&|?")
    for c in text:
        if quote:
            out.append(c)
            if c == quote:
                quote = None
            continue
        if c in "'\"":
            quote = c
        if c in " \n" and out and (out[-1] in punct or out[-1] in " \n"):
            continue
        if c in punct:
            while out and out[-1] in " \n":
                out.pop()
        out.append(c)
    return "".join(out)


style_end = head.index("</style>")
head = squeeze(head[:style_end]) + squeeze(head[style_end:])
body = head.encode("utf-8")
# One C token per byte; octal escapes are always 3 digits, so they can't merge
# with a following digit or be split across the adjacent string literals.
toks = []
for b in body:
    c = chr(b)
    if b == 10:
        toks.append("\\n")
    elif 32 <= b < 127 and c not in '"\\?':
        toks.append(c)
    else:
        toks.append(f"\\{b:03o}")
plines = [
    "// Generated by scripts/embed_web.py from web/portal.html. Do not edit.",
    "#pragma once",
    "#include <Arduino.h>",
    "",
    "static const char kPortalHead[] PROGMEM =",
]
for i in range(0, len(toks), 96):
    plines.append('  "' + "".join(toks[i:i + 96]) + '"')
plines[-1] += ";"
ptext = "\n".join(plines) + "\n"
pout = os.path.join(out_dir, "portal_head.h")
pold = None
if os.path.exists(pout):
    with open(pout, "r", encoding="utf-8") as f:
        pold = f.read()
if pold != ptext:
    with open(pout, "w", encoding="utf-8", newline="\n") as f:
        f.write(ptext)
print(f"embed_web: portal.html -> {len(body)} B")
